var { helperFits, worldOf } = Scripts.engine;
var { islView } = Scripts.island;
var { BRAIN_SIZES, CREW_CAP, UPGRADES, balanceOf, blueprintSpec, buildingDone, jobRobotId, landOf, modelOf,
  robotKindOf, robotRowsOf, robotSpec, shopItem } = Scripts.save;
var SHOP_TABS_LIST = ["build","animals","robots","upgrades","helpers"];
var SHOP_TAB_WORDS = {"build":"iw6hTabBuild","animals":"iw6hTabAnimals","robots":"iw6hTabRobots","upgrades":"iw6hTabUpgrades","helpers":"iw6hTabHelpers"};
var SHOP_FIRST_TAB = "robots";
var SHOP_IDS = {"tab":"shoptab-","item":"shopitem-","robot":"shopbot-","plot":"shopplot-"};
function shLang(v) { return String(v) === 'fr' ? 'fr' : 'en'; }
function shWords(rows, lang) { var map = {}, list = Array.isArray(rows) ? rows : []; for (var i = 0; i < list.length; i++) if (list[i] && list[i].key) map[list[i].key] = String(list[i][lang] || list[i].en || ''); return map; }
function shFill(text, vars) { var t = String(text || ''); for (var k in vars) t = t.split('{' + k + '}').join(String(vars[k])); return t; }
/** A row id or a bare id: the bare id (a chip publishes its row's id). */
function shBare(v, prefix) { var s = String(v === undefined || v === null ? '' : v); return s.indexOf(prefix) === 0 ? s.slice(prefix.length) : s; }
function shActive(model) { for (var i = 0; i < model.profiles.length; i++) if (model.profiles[i].id === model.island.activeId) return model.profiles[i]; return null; }
function shModel(raw) { return modelOf(raw && typeof raw === 'object' ? raw : {}); }
/** An upgrade she has — an islander's gift before the shop (a sticker) or bought. */
function shHasUpgrade(p, up) { return !!p && (p.owned.indexOf(up) !== -1 || p.stickers.indexOf(up) !== -1); }
function shUpgradeSpec(id) { for (var i = 0; i < UPGRADES.length; i++) if (UPGRADES[i].id === id) return UPGRADES[i]; return null; }
/** Does the shop show this item to her? (See the module's rules.) */
function shShows(p, it) {
  if (!p || !it) return false;
  if (it.kind === 'robot') return !!jobRobotId(p, it.robot);
  if (it.kind === 'upgrade') {
    if (shHasUpgrade(p, it.upgrade)) return true;
    var up = shUpgradeSpec(it.upgrade);
    if (!up || p.island.done.indexOf(up.unlockedBy) === -1) return false;
    var rows = robotRowsOf(p);
    for (var i = 0; i < rows.length; i++) if (up.fits.indexOf(rows[i].kind) !== -1) return true;
    return false;
  }
  // P108 IW-007 (lane A): an animal shows once a refuge on her land is finished (iw7aShows, iw007Animals.ts).
  if (it.kind === 'animal') return iw7aShows(p, it);
  // P108 IW-007 (s5 base): the blueprints and animals are in the catalogue, but their shelves stay shut (the "later" line)
  // until lane B opens Build and lane A opens Animals.
  // P108 IW-007 (lane B): the Build tab is open — every blueprint (one she bought says where it is: BUILD_SHOP).
  if (it.kind === 'blueprint') return true;
  if (it.kind === 'animal') return false;
  return true;
}

// ── P108 IW-007 (lane B): the Build tab ──
function iw7bBuiltOf(p, bp) { var l = landOf(p && p.island ? p.island.land : null); for (var i = 0; i < l.buildings.length; i++) if (l.buildings[i].bp === bp) return l.buildings[i]; return null; }
/** Where a blueprint she owns is: 'place' (bought, not placed), 'building', 'built' — '' when she does not own it. */
function iw7bBpState(p, it) {
  if (!p || !it || it.kind !== 'blueprint' || p.owned.indexOf(it.id) === -1) return '';
  var b = iw7bBuiltOf(p, it.blueprint);
  return !b ? 'place' : buildingDone(b) ? 'built' : 'building';
}
function iw7bBpTag(p, it, W) { var st = iw7bBpState(p, it); return st === 'place' ? W.iw7bTagPlace || '' : st === 'building' ? W.iw7bTagBuilding || '' : st === 'built' ? W.iw7bTagBuilt || '' : ''; }
function iw7bBpCardLine(p, it, W) { var st = iw7bBpState(p, it); return st === 'place' ? W.iw7bCardPlace || '' : st === 'building' ? W.iw7bCardBuilding || '' : st === 'built' ? W.iw7bCardBuilt || '' : ''; }


// ── P108 IW-007 (lane A): the Animals shelf ──
var IW7A_DEFAULT_NAMES = {"rabbit":{"en":"Hazel","fr":"Noisette"},"sheep":{"en":"Cloud","fr":"Nuage"}};
var IW7A_KINDS = ["rabbit","sheep"];
/** Her land's finished refuges (a building whose blueprint does 'animals' and has every material). */
function iw7aRefuges(p) {
  var out = [];
  if (!p || !p.island) return out;
  var land = landOf(p.island.land);
  for (var i = 0; i < land.buildings.length; i++) { var spec = blueprintSpec(land.buildings[i].bp); if (spec && spec.does === 'animals' && spec.pen && buildingDone(land.buildings[i])) out.push(land.buildings[i]); }
  return out;
}
/** The Animals shelf is open: a refuge on her land is finished (buyItem's own test for 'refuge'). */
function iw7aOpen(p) { return iw7aRefuges(p).length > 0; }
/** A free place in a finished refuge's pen (buyItem's own test for 'pen'). */
function iw7aPenFree(p) {
  var rs = iw7aRefuges(p), land = landOf(p && p.island ? p.island.land : null);
  for (var i = 0; i < rs.length; i++) {
    var spec = blueprintSpec(rs[i].bp);
    for (var s = 0; s < spec.pen; s++) { var used = false; for (var a = 0; a < land.animals.length; a++) if (land.animals[a].at === rs[i].id && land.animals[a].slot === s) used = true; if (!used) return true; }
  }
  return false;
}
/** Does the shop show this animal? Only once the shelf is open. */
function iw7aShows(p, it) { return !!it && it.kind === 'animal' && IW7A_KINDS.indexOf(it.animal) !== -1 && iw7aOpen(p); }
/** The name an animal of this kind takes when she types none: the kind's name in her language, numbered when taken. */
function iw7aDefaultName(p, kind) {
  var names = IW7A_DEFAULT_NAMES[kind];
  if (!names) return '';
  var base = names[p && p.lang === 'fr' ? 'fr' : 'en'], taken = {};
  var land = landOf(p && p.island ? p.island.land : null);
  for (var a = 0; a < land.animals.length; a++) taken[land.animals[a].name] = 1;
  if (!taken[base]) return base;
  for (var n = 2; n < 99; n++) if (!taken[base + ' ' + n]) return base + ' ' + n;
  return base;
}
/** The line an open tab says: the Animals tab, shut, says build the refuge first; open, nothing. Other tabs as they were. */
function iw7aLater(tab, later, p, W) {
  if (tab !== 'animals') return later;
  return iw7aOpen(p) ? '' : W.iw7aShut || later;
}
/** Why an animal's card has no Buy ('' when it may be bought): no finished refuge, or every place of its pen taken. */
function iw7aRefusal(p, W) {
  if (!iw7aOpen(p)) return W.iw7aNoRefuge || '';
  if (!iw7aPenFree(p)) return W.iw7aPenFull || '';
  return '';
}
/** The line after Buy: the newest animal of that kind is waiting by her bowl on her land. */
function iw7aBoughtLine(p, it, W) {
  var land = landOf(p && p.island ? p.island.land : null), last = null;
  for (var a = 0; a < land.animals.length; a++) if (land.animals[a].kind === it.animal) last = land.animals[a];
  if (!last) return '';
  var line = W['iw7aBought_' + it.animal] || W.iw7aBought_rabbit || '';
  return line.split('{name}').join(last.name || iw7aDefaultName(p, it.animal));
}


var lang = shLang(Inputs.lang), W = shWords(Inputs.words, lang);
var model = shModel(Inputs.model), p = shActive(model);
var id = shBare(Inputs.itemId, SHOP_IDS.item), it = p ? shopItem(id) : null;
var reqs = Array.isArray(Inputs.requests) ? Inputs.requests : [];
var bal = balanceOf(p);
var out = { showCard: false, itemId: '', icon: '', name: '', line: '', have: '', cost: '', left: '', showLeft: false, short: '', showShort: false, canBuy: false, showName: false, namePlaceholder: '', showRobots: false, robots: [], robotId: '', showUse: false, plots: [], plotId: '', canUse: false, none: '', showNone: false, done: '', showDone: false, showFigures: false };
var rows = p ? robotRowsOf(p) : [];
function nameOfRobot(rid) { for (var n = 0; n < rows.length; n++) if (rows[n].id === rid) return rows[n].name; return ''; }
function titleOf(reqId, botName) { for (var q = 0; q < reqs.length; q++) if (reqs[q] && reqs[q].id === reqId && reqs[q].copyKeys) return (W[reqs[q].copyKeys.title] || reqId).split('{b}').join(botName || 'Pip'); return reqId; }
if (it && shShows(p, it)) {
  out.showCard = true;
  out.itemId = it.id;
  out.icon = it.icon;
  out.name = it.name[lang] || it.name.en;
  out.line = it.line[lang] || it.line.en;
  var held = it.kind === 'helper' && p.owned.indexOf(it.id) !== -1;
  var yours = it.kind === 'upgrade' && shHasUpgrade(p, it.upgrade);
  // P108 IW-007 (lane B): a blueprint she bought has no Buy: its card says where it is (to place on her land, built…).
  var bpLine = it.kind === 'blueprint' ? iw7bBpCardLine(p, it, W) : '';
  if (bpLine) { yours = true; }
  if (held) {
    // A held helper: the jobs it helps now — a pinned robot at work on a job not done yet, the helper fitting it.
    var st = Inputs.state && typeof Inputs.state === 'object' && Array.isArray(Inputs.state.plots) ? Inputs.state : null, ids = [];
    if (st) for (var k = 0; k < st.plots.length; k++) {
      var plot = st.plots[k], cur = st.live && st.live[plot.id];
      if (plot.status !== 'working' || !plot.job || plot.stale || !cur || cur.phase === 'wait' || cur.helper) continue;
      if (!helperFits(worldOf(islView(plot, cur)), it.helper)) continue;
      ids.push(plot.id);
      out.plots.push({ id: SHOP_IDS.plot + plot.id, label: titleOf(plot.id, nameOfRobot(plot.robotId)), selected: false, locked: false });
    }
    var want = shBare(Inputs.plotId, SHOP_IDS.plot);
    out.plotId = ids.indexOf(want) !== -1 ? want : ids.length === 1 ? ids[0] : '';
    for (var s = 0; s < out.plots.length; s++) out.plots[s].selected = out.plots[s].id === SHOP_IDS.plot + out.plotId;
    out.showUse = ids.length > 0;
    out.canUse = !!out.plotId;
    if (!ids.length) out.none = W.iw6hNoJob || '';
  } else if (yours) {
    out.done = bpLine || W.iw6hYoursLine || '';
  } else {
    out.showFigures = true;
    out.have = shFill(W.iw6hHave, { n: bal });
    out.cost = shFill(W.iw6hCost, { n: it.price });
    // P109 ISL-005: refused, not blocked: a hoisted var blocked replaced ENGINE's blocked() for the whole run.
    var can = bal >= it.price, refused = false;
    if (it.kind === 'robot') {
      if (p.island.robots.length >= CREW_CAP) { refused = true; out.none = shFill(W.iw6hFull, { n: CREW_CAP }); }
      else {
        var spec = robotSpec(it.robot), count = 1;
        for (var c = 0; c < p.island.robots.length; c++) if (robotKindOf(p.island.robots[c]) === it.robot) count++;
        out.namePlaceholder = spec ? (spec.defaultName[lang] || spec.defaultName.en) + ' ' + count : '';
        out.showName = can;
      }
    } else if (it.kind === 'brain') {
      // Only a robot at the size before this one (12 → 16 → 20); one alone is chosen for her.
      var before = BRAIN_SIZES[BRAIN_SIZES.indexOf(it.size) - 1], okIds = [];
      for (var b = 0; b < rows.length; b++) if (rows[b].brain === before) { okIds.push(rows[b].id); out.robots.push({ id: SHOP_IDS.robot + rows[b].id, label: shFill(W.iw6hBrainOf, { r: rows[b].name, n: rows[b].brain }), selected: false, locked: false }); }
      var pick = shBare(Inputs.robotId, SHOP_IDS.robot);
      out.robotId = okIds.indexOf(pick) !== -1 ? pick : okIds.length === 1 ? okIds[0] : '';
      for (var o = 0; o < out.robots.length; o++) out.robots[o].selected = out.robots[o].id === SHOP_IDS.robot + out.robotId;
      out.showRobots = okIds.length > 0;
      if (!okIds.length) { refused = true; out.none = W.iw6hNoBrain || ''; }
      else if (!out.robotId) refused = true;
    } else if (it.kind === 'animal') {
      // P108 IW-007 (lane A): an animal's card has the copy's name box (an empty box takes iw7aDefaultName); a pen with no
      // free place (or no finished refuge) says so and has no Buy.
      var iw7aWhy = iw7aRefusal(p, W);
      if (iw7aWhy) { refused = true; out.none = iw7aWhy; }
      else { out.namePlaceholder = iw7aDefaultName(p, it.animal); out.showName = can; }
    }
    if (can) { out.left = shFill(W.iw6hLeft, { n: bal - it.price }); out.showLeft = true; }
    else { var more = it.price - bal; out.short = shFill(more === 1 ? W.iw6hShort1 : W.iw6hShort, { n: more }); out.showShort = true; }
    out.canBuy = can && !refused;
  }
  // What the last Buy / Use it did, on this item's card — and, the moment after, only that: never "you need N more" under
  // "It's yours!" (the drive's first look at the card just bought). A helper just bought goes on to its jobs.
  var used = String(Inputs.used || '').split('|'), justBought = String(Inputs.bought || '') === it.id, justUsed = used[0] === it.id && !!used[1];
  // P108 IW-007 (lane B): a blueprint just bought says where it goes ("It's yours! Tap your land…").
  if (justBought) out.done = (it.kind === 'blueprint' && bpLine) || W.iw6hBought || '';
  // P108 IW-007 (lane A): an animal just bought — who is waiting by her bowl on her land.
  if (justBought && it.kind === 'animal') out.done = iw7aBoughtLine(p, it, W) || out.done;
  if (justUsed) out.done = shFill(W.iw6hUsed, { what: out.name, plot: titleOf(used[1], nameOfRobot(p.island.plots[used[1]] ? p.island.plots[used[1]].robotId : '')) });
  if ((justBought && !held) || justUsed) { out.showFigures = false; out.showLeft = false; out.showShort = false; out.canBuy = false; out.showName = false; out.showRobots = false; out.none = ''; }
  out.showDone = !!out.done;
  out.showNone = !!out.none;
}
Outputs.showCard = out.showCard;
Outputs.itemId = out.itemId;
Outputs.icon = out.icon;
Outputs.name = out.name;
Outputs.line = out.line;
Outputs.have = out.have;
Outputs.cost = out.cost;
Outputs.left = out.left;
Outputs.showLeft = out.showLeft;
Outputs.short = out.short;
Outputs.showShort = out.showShort;
Outputs.canBuy = out.canBuy;
Outputs.showName = out.showName;
Outputs.namePlaceholder = out.namePlaceholder;
Outputs.showRobots = out.showRobots;
Outputs.robots = out.robots;
Outputs.robotId = out.robotId;
Outputs.showUse = out.showUse;
Outputs.plots = out.plots;
Outputs.plotId = out.plotId;
Outputs.canUse = out.canUse;
Outputs.none = out.none;
Outputs.showNone = out.showNone;
Outputs.done = out.done;
Outputs.showDone = out.showDone;
Outputs.showFigures = out.showFigures;
